        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void SetupLocate(
            ref string? exeOrDbgPath,
            IFile? file,
            SearchFlags flags,
            ref string? searchPath,
            out bool ownsPEFile,
            out State state,
            out LocatorContext ctx,
            out bool run)
        {
            if (exeOrDbgPath == null && file == null)
                throw new ArgumentNullException(nameof(exeOrDbgPath));

            ownsPEFile = true;

            if (file != null)
            {
                ownsPEFile = false;
                exeOrDbgPath = file.FileName;

                if (exeOrDbgPath == null)
                    throw new ArgumentException("The specifid file does not have a FileName");
            }

            /* Systems often don't have _NT_SYMBOL_PATH defined, so it's up to us to define it for them. The way we'll do this is we'll say if it's not defined,
             * we'll append it to the user's custom search path and store any symbols we locate in %temp%
             *
             * Note that when RDP'd into a server, the temp path may include a session number at the end, and that folder
             * may not actually exist. When we go to save the file, we'll check if this directory exists, and if not create it */
            if (string.IsNullOrEmpty(Environment.GetEnvironmentVariable("_NT_SYMBOL_PATH")))
            {
                const string extraSearchPath = "srv*%temp%\\symbols*http://msdl.microsoft.com/download/symbols";

                if (searchPath == null)
                    searchPath = extraSearchPath;
                else
                {
                    using var builder = new ValueStringBuilder(searchPath.Length + extraSearchPath.Length + 1);
                    builder.Append(searchPath);
                    builder.Append(';');
                    builder.Append(extraSearchPath);

                    searchPath = builder.ToString();
                }
            }

            state = State.None;

            ctx = new LocatorContext
            {
                Flags = flags,
                SearchPath = searchPath,
            };

            run = true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool ReadFile(
            string? exeOrDbgPath,
            IFile? file,
            ref LocatorContext ctx,
            ref State state,
            ref bool run)
        {
            if ((ctx.File = file!) != null || Detector.TryOpenFile(exeOrDbgPath, out ctx.File))
            {
                switch (ctx.File.Kind)
                {
                    case FileKind.PE:
                        var peFile = (PEFile) ctx.File;
                        ctx.DebugTable = peFile.DebugTable;
                        state = State.ReadDebugTable;

                        var dot = exeOrDbgPath.LastIndexOf('.');

                        if (dot == -1)
                            ctx.PEFileExt = string.Empty;
                        else
                            ctx.PEFileExt = exeOrDbgPath.Substring(dot + 1);

                        ctx.Stripped = (peFile.FileHeader.Characteristics & IMAGE_FILE.IMAGE_FILE_DEBUG_STRIPPED) != 0;
                        ctx.PETimeDateStamp = peFile.FileHeader.TimeDateStamp;
                        ctx.PESizeOfImage = peFile.OptionalHeader.SizeOfImage;

                        if (exeOrDbgPath!.EndsWith(".ni.exe") || exeOrDbgPath.EndsWith(".ni.dll"))
                        {
                            //Possible NGEN file
                            if (peFile.NgenHeader != null)
                                ctx.NGEN = true;
                        }

                        break;

                    case FileKind.DBG:
                        ctx.DBGFilePath = exeOrDbgPath;
                        ctx.DebugTable = ((DBGFile) ctx.File).DebugTable;
                        state = State.ReadDebugTable;

                        break;

                    case FileKind.DOS:
                    case FileKind.NE:
                    case FileKind.LE:
                        //Look for *.sym, *.dbg or *.pdb files in the same directory as us
                        state = State.ReadAnyLocal;

                        break;

                    default:
                        return false;
                }
            }
            else
                run = false;

            return true;
        }

