                builder.Append("pdb");
                var candidatePath = builder.ToString();

                if (File.Exists(candidatePath))
                {
                    ctx.PDBFilePath = candidatePath;
                    return true;
                }

                //Is there a .dbg file?
                builder.Length = pos;
                builder.Append("dbg");
                candidatePath = builder.ToString();

                if (File.Exists(candidatePath))
                {
                    ctx.DBGFilePath = candidatePath;
                    return true;
                }

                //Is there a .sym file?
                builder.Length = pos;
                builder.Append("sym");
                candidatePath = builder.ToString();

                if (File.Exists(candidatePath))
                {
                    ctx.SYMFilePath = candidatePath;
                    return true;
                }

                if (searchPath != null)
                {
                    //Try our search path as well. Note that we're not going to allow searching remote so we can just
                    //call the non-async version

                    builder.Clear();
                    var nameWithoutExt = Path.GetFileNameWithoutExtension(exeOrDbgPath);
                    builder.Append(nameWithoutExt);
                    builder.Append(".pdb");

                    var nameToLocate = builder.ToString();

                    string ext;

                    if (dot == -1)
                        ext = string.Empty;
                    else
                        ext = exeOrDbgPath.Substring(dot + 1);

                    fixed (char* p = nameToLocate)
                    {
                        var extSpan = new Span<char>(p + nameWithoutExt.Length + 1, 3);

                        var result = LocateFileInPath(null, nameToLocate, searchPath, ext, default, null, allowRemote: false, LocatorHttpPolicy.None, null, default);

                        if (result.fileInPath != null)
                        {
                            ctx.PDBFilePath = candidatePath;
                            return true;
                        }

                        "dbg".AsSpan().CopyTo(extSpan);

                        result = LocateFileInPath(null, nameToLocate, searchPath, ext, default, null, allowRemote: false, LocatorHttpPolicy.None, null, default);

                        if (result.fileInPath != null)
                        {
                            ctx.DBGFilePath = candidatePath;
                            return true;
                        }

                        "sym".AsSpan().CopyTo(extSpan);

                        result = LocateFileInPath(null, nameToLocate, searchPath, ext, default, null, allowRemote: false, LocatorHttpPolicy.None, null, default);

                        if (result.fileInPath != null)
                        {
                            ctx.SYMFilePath = candidatePath;
                            return true;
                        }
                    }
                }

                return false;
            }
            finally
            {
                builder.Dispose();
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool ParseMisc(ref LocatorContext ctx, ref bool ownsPEFile, ref bool run)
        {
            Debug.Assert(ctx.DBGFilePath != null);

            if (Detector.TryOpenFile(ctx.DBGFilePath, out var dbgFile))
            {
                if (dbgFile is not DBGFile d)
                {
                    dbgFile.Dispose();
                    run = false;
                    return false;
                }

                if (!ownsPEFile)
                {
                    //We're replacing the file with the DBGFile, so we _will_ need to dispose that when we're done
                    ownsPEFile = false;
                }
                ctx.File = d;

                ctx.Stripped = false;
                ctx.DebugTable = d.DebugTable;

                //Now read the debug table like normal
                return true;
            }
            else
            {
                run = false;
                return false;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static (Artifacts? artifacts, SymStoreKey? symStoreKey) CreateArtifacts(ref LocatorContext ctx)
        {
            //Success is dictated by whether we found anything
            if (ctx.DBGFilePath == null && ctx.PDBFilePath == null && ctx.SYMFilePath == null && ctx.MPDBIndex == null)
                return default;

            ArtifactKind bestKind;

            if (ctx.PDBFilePath != null)
                bestKind = ArtifactKind.PDB;
            else if (ctx.MPDBIndex != null)
                bestKind = ArtifactKind.EmbeddedPortablePdb;
            else if (ctx.DBGFilePath != null)
                bestKind = ArtifactKind.DBG;
            else
            {
                Debug.Assert(ctx.SYMFilePath != null);
                bestKind = ArtifactKind.SYM;
            }

            return (new Artifacts(bestKind, ctx.DBGFilePath, ctx.PDBFilePath, ctx.SYMFilePath, ctx.MPDBIndex), ctx.SymStoreKey);
        }

        #endregion
        #region ReadDebugTable

        private static State ReadDebugTable(LocatorContext ctx, LocatorHttpPolicy httpPolicy, ILocatorProgress progress, CancellationToken cancellationToken)
        {
            if (ctx.DebugTable == null)
                return default;

            for (int i = 0; i < ctx.DebugTable.Length; i++)
            {
                ImageDebugDirectory debugDir = ctx.DebugTable[i];

                switch (debugDir.Type)
                {
                    case IMAGE_DEBUG_TYPE_MISC:
                        //It's possible for a *.dbg file to have a misc entry pointing back to the *.exe file. We only process misc entries when we're stripped,
                        //meaning we're processing the original PE file
                        if (ctx.Stripped && (ctx.Flags & SearchFlags.DBG) != 0 && debugDir.Data is ImageDebugMisc m)
                        {
                            var str = m.Data.ToString();

                            var symSrvIndex = SymStoreKey.FromMisc(str, ctx.PETimeDateStamp, ctx.PESizeOfImage);

                            var path = LocateDBGFile(ctx.File, str, ctx.SearchPath, ctx.PEFileExt, symSrvIndex, httpPolicy, progress, cancellationToken);

                            //If we've already found a file in another record, don't blow it away because we didn't find one in this one
                            if (path.filePath != null)
                            {
                                ctx.DBGFilePath = path.filePath;
                                ctx.SymStoreKey = path.keyUsed;
                                return State.ReadMiscDebugTable;
                            }
                        }
                        break;

                    case IMAGE_DEBUG_TYPE_CODEVIEW:
                        if ((ctx.Flags & SearchFlags.PDB) != 0 && debugDir.Data is ICodeViewPDB c)
                        {
                            var pdbName = c.Path.ToString();

                            if (ctx.NGEN)
                            {
                                if (!pdbName.EndsWith(".ni.pdb"))
                                    continue;
                            }
                            else
                            {
                                if (pdbName.EndsWith(".ni.pdb"))
                                    continue;
                            }

                            /* Per LOCATOR::FLocatePdb, if the debug directory's minor version is PORTABLE_PDB_MINOR_VERSION (20557) then
                             * this indicates that the PDB may in fact be a portable PDB, which can be resolved on the symbol server by
                             * specifying an age of -1. LOCATOR::FLocatePdb tries for a normal PDB first, and if that fails tries for
                             * a portable one. Visual Studio does not use LOCATOR, and if it sees that PORTABLE_PDB_MINOR_VERSION is present,
                             * it may attempt to do a direct lookup with a negative age specified */
                            SymStoreKey symSrvIndex;
                            SymStoreKey? altSymSrvIndex = null;

                            if (c is RSDSI r)
                            {
                                var rsdsPath = r.Path.ToString();

                                symSrvIndex = SymStoreKey.FromRSDSI(rsdsPath, r.Guid, r.Age);

                                if (debugDir.IsPortablePDB)
                                    altSymSrvIndex = SymStoreKey.FromRSDSI(rsdsPath, r.Guid, -1);
                            }
                            else
                            {
                                //I would not expect anything using NB10 to be using portable PDBs
                                symSrvIndex = SymStoreKey.FromNB10((NB10I) c);
                            }

                            var path = LocatePDBFile(ctx.File, pdbName, ctx.SearchPath, ctx.PEFileExt, symSrvIndex, altSymSrvIndex, httpPolicy, progress, cancellationToken);

                            //If we've already found a file in another record, don't blow it away because we didn't find one in this one
                            if (path.fileInPath != null)
                            {
                                ctx.PDBFilePath = path.fileInPath;
                                ctx.SymStoreKey = path.keyUsed;
                                return State.End;
                            }
                        }
                        break;

                    case IMAGE_DEBUG_TYPE_EMBEDDED_PORTABLE_PDB:
                        if ((ctx.Flags & SearchFlags.MPDB) != 0 && debugDir.Data is EmbeddedPortablePdb)
                        {
                            ctx.MPDBIndex = i;
                            return State.End;
                        }
                        break;
                }
            }

            return default;
        }

