        #region LocateFileInPath

        private static (string? fileInPath, SymStoreKey? keyUsed) LocateFileInPath(
            IFile? file,
            string nameAndExt,
            string? searchPath,
            string? peFileExt,
            SymStoreKey symSrvIndex,
            SymStoreKey? altSymSrvIndex,
            bool allowRemote,
            LocatorHttpPolicy httpPolicy,
            ILocatorProgress progress,
            CancellationToken cancellationToken)
        {
            if (searchPath == null)
                return default;

            var remainingSearchPath = new SpanInfo(searchPath);

            var builder = new ValueStringBuilder.NonRef(256);

            try
            {
                var run = true;

                while (run)
                {
                    //We can't store a ReadOnlySpan in the async version of the method, so we'll store the bounds here instead
                    SpanInfo currentPath = default; //I can't pass this to LocateFileInPathLocal for some reason if this is returned as an out parameter from LocateFileInPathSetup

                    if (!LocateFileInPathSetup(ref remainingSearchPath, ref currentPath, ref run, out var symSrv, out var cache))
                        return default;

                    if (symSrv || cache)
                    {
                        if (allowRemote)
                        {
                            var result = SymStore.GetFile(file, currentPath.Span, symSrvIndex, altSymSrvIndex, httpPolicy, progress, cancellationToken);

                            if (result.filePath != null)
                                return result;
                        }
                    }
                    else
                    {
                        if (LocateFileInPathLocal(ref builder, currentPath.Span, nameAndExt, peFileExt, out var str))
                            return (str, null);
                    }
                }

                return default;
            }
            finally
            {
                builder.Dispose();
            }
        }

#if !NATIVEAOT
        private static async ValueTask<(string? fileInPath, SymStoreKey? keyUsed)> LocateFileInPathAsync(
            IFile? file,
            string nameAndExt,
            string? searchPath,
            string? peFileExt,
            SymStoreKey symSrvIndex,
            SymStoreKey? altSymSrvIndex,
            bool allowRemote,
            LocatorHttpPolicy httpPolicy,
            ILocatorProgress progress,
            CancellationToken cancellationToken)
        {
            if (searchPath == null)
                return default;

            var remainingSearchPath = new SpanInfo(searchPath);

            var builder = new ValueStringBuilder.NonRef(256);

            try
            {
                var run = true;

                while (run)
                {
                    //We can't store a ReadOnlySpan in the async version of the method, so we'll store the bounds here instead
                    SpanInfo currentPath = default; //I can't pass this to LocateFileInPathLocal for some reason if this is returned as an out parameter from LocateFileInPathSetup

                    if (!LocateFileInPathSetup(ref remainingSearchPath, ref currentPath, ref run, out var symSrv, out var cache))
                        return default;

                    if (symSrv || cache)
                    {
                        if (allowRemote)
                        {
                            var result = await SymStore.GetFileAsync(file, currentPath.Span, symSrvIndex, altSymSrvIndex, httpPolicy, progress, cancellationToken).ConfigureAwait(false);

                            if (result.filePath != null)
                                return result;
                        }
                    }
                    else
                    {
                        if (LocateFileInPathLocal(ref builder, currentPath.Span, nameAndExt, peFileExt, out var str))
                            return (str, null);
                    }
                }

                return default;
            }
            finally
            {
                builder.Dispose();
            }
        }
#endif
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool LocateFileInPathSetup(ref SpanInfo remainingSearchPath, ref SpanInfo currentPath, ref bool run, out bool symSrv, out bool cache)
        {
            var index = remainingSearchPath.IndexOf(";".AsSpan(), StringComparison.OrdinalIgnoreCase);

            if (index == -1)
            {
                run = false;
                currentPath = remainingSearchPath; //Use the rest of the path

                remainingSearchPath = default;
            }
            else
            {
                currentPath = remainingSearchPath.Slice(0, index);

                //Update the current position for the next loop round
                remainingSearchPath = remainingSearchPath.Slice(index + 1);
            }

            symSrv = false;
            cache = false;

            if (currentPath.StartsWith("srv*".AsSpan(), StringComparison.OrdinalIgnoreCase))
            {
                symSrv = true;
                currentPath = currentPath.Slice(4);
            }
            else if (currentPath.StartsWith("symsrv*".AsSpan(), StringComparison.OrdinalIgnoreCase))
            {
                //Only symsrv.dll is supported
                if (!currentPath.StartsWith("symsrv*symsrv.dll*".AsSpan(), StringComparison.OrdinalIgnoreCase))
                    return false;

                symSrv = true;
                currentPath = currentPath.Slice(18);
            }

            return true;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool LocateFileInPathLocal(
            ref ValueStringBuilder.NonRef builder,
            ReadOnlySpan<char> currentPath,
            string nameAndExt,
            string? peFileExt,
            out string str)
        {
            builder.Clear();

            builder.Append(currentPath);

            if (!currentPath.EndsWith("\\".AsSpan()) && !currentPath.EndsWith("/".AsSpan()))
                builder.Append("\\");

            var prefix = builder.Length;

            const string symbolsPrefix = "symbols\\";

            builder.Append(symbolsPrefix);

            if (peFileExt != null)
            {
                builder.Append(peFileExt);
                builder.Append('\\');
            }

            builder.Append(nameAndExt);

            str = builder.ToString();

            if (File.Exists(str))
                return true;

            //Try without symbols\ prefix
            builder.Remove(prefix, symbolsPrefix.Length);

            str = builder.ToString();

            if (File.Exists(str))
                return true;

            if (peFileExt != null)
            {
                //If a PE File extension was specified, try without that now too
                builder.Remove(prefix, peFileExt.Length + 1);
                str = builder.ToString();

                if (File.Exists(str))
                    return true;
            }

            return false;
        }

        #endregion

        [Flags]
        enum SearchFlags
        {
            DBG = 1,
            PDB = 2,
            MPDB = 4,
            All = DBG | PDB | MPDB
        }

        public readonly struct Artifacts
        {
            public ArtifactKind BestKind { get; }

            public string? DBGPath { get; }

            public string? PDBPath { get; }

            //Only valid when the input file is a DOS, NE or LE file
            public string? SYMPath { get; }

            /// <summary>
            /// Gets the index of the <see cref="ImageDebugDirectory"/> that contains <see cref="EmbeddedPortablePdb"/> data.<para/>
            /// If this value is <see langword="null"/>, embedded portable PDB metadata is not available.
            /// </summary>
            public int? EmbeddedPortablePdbIndex { get; } //Note that this can't be the EmbeddedPortablePdb itself, because if only a path to a PEFile was passed in, we'll have opened and then closed the file

            public Artifacts(ArtifactKind bestKind, string? dbgPath, string? pdbPath, string? symPath, int? embeddedPortablePdbIndex)
            {
                BestKind = bestKind;
                DBGPath = dbgPath;
                PDBPath = pdbPath;
                SYMPath = symPath;
                EmbeddedPortablePdbIndex = embeddedPortablePdbIndex;
            }
        }

        public enum ArtifactKind
        {
            SYM = 1,
            DBG = 2,
            EmbeddedPortablePdb = 3,
            PDB = 4,
        }

        internal enum State
        {
            //The initial state. Read headers to find out what type of file it is
            None,

            //Read the debug table of the input *.exe or *.dbg file
            ReadDebugTable,

            //Read the debug table of a *.dbg file pointed to by an *.exe file
            ReadMiscDebugTable,

            //It's a DOS, NE or LE file; accept any *.sym, *.dbg or *.pdb file located in the same
            //directory as the input file
            ReadAnyLocal,

            End
        }

        internal struct SpanInfo
        {
            public string Value;
            public int StartIndex;
            public int Length;

            public SpanInfo(string value)
            {
                Value = value;
                Length = value.Length;
            }

            public ReadOnlySpan<char> Span => Value.AsSpan(StartIndex, Length);

            public override string ToString() => Span.ToString();

            public SpanInfo Slice(int startIndex) => new SpanInfo { Value = Value, StartIndex = StartIndex + startIndex, Length = Length - startIndex };

            public SpanInfo Slice(int startIndex, int length) => new SpanInfo { Value = Value, StartIndex = StartIndex + startIndex, Length = length };

            public int IndexOf(ReadOnlySpan<char> value, StringComparison comparisonType) => Span.IndexOf(value, comparisonType);

            public bool StartsWith(ReadOnlySpan<char> value, StringComparison comparisonType) => Span.StartsWith(value, comparisonType);
        }
    }
}
